Device.typescript:
interface Device {
  id: string;
  ip: string | null;
  mac: string | null;
  hostname: string | null;
  vendor: string | null;
  device_type: string | null;
  status: 'up' | 'down' | 'unknown';
  first_seen: number | null;
  last_seen: number | null;
  tags: Record<string, string>;
}

LatencyPoint.typescript:
interface LatencyPoint {
  ts: number;
  ms: number;
  loss: number;
}

DiscoveryScanRequest.typescript:
interface DiscoveryScanRequest {
  cidr?: string | null;
  interface?: string | null;
  arp_timeout?: number | null;
  ping_timeout?: number | null;
  persist?: boolean;
  identify?: boolean;
}

DiscoveryScanResponse.typescript:
interface DiscoveryScanResponse {
  count: number;
  devices: Array<{
    ip?: string;
    mac?: string;
    hostname?: string;
    vendor?: string;
    source?: string;
  }>;
  persisted: boolean;
  identified: boolean;
}

WebSocketMessage.typescript:
type WebSocketMessage =
  | { type: 'hello'; ts: number }
  | { type: 'device_discovered'; ts: number; device: Device }
  | { type: 'device_up'; ts: number; device_id: string }
  | { type: 'device_down'; ts: number; device_id: string }
  | { type: 'latency'; ts: number; device_id: string; ms: number; loss: number };

PingResult.typescript:
interface PingResult {
  ip: string;
  status: 'up' | 'down' | 'error';
  latency_avg: number | null;
  latency_min: number | null;
  latency_max: number | null;
  packet_loss: number;
}

SNMPIdentification.typescript:
interface SNMPIdentification {
  hostname: string | null;
  description: string | null;
  uptime: string | null;
  contact: string | null;
  location: string | null;
  object_id: string | null;
}
